typedef struct {
    float x, y;          /* primary data */
    float world;         /* cached derived data */
    bool dirty;          /* set by every mutator */
} node;

void node_move(node *n, float dx) { n->x += dx; n->dirty = true; }

float node_world(node *n) {                   /* accessor */
    if (n->dirty) { n->world = world_of(n); n->dirty = false; }
    return n->world;
}
